# Abstraction interfaces for WebSocket protocol handling
# This module introduces low-coupling interfaces without changing behavior

class HandshakeHandler:
    """Interface for WebSocket handshake validation and response generation"""
    def validate_request(self, headers):
        """Validate incoming HTTP headers for WebSocket upgrade"""
        raise NotImplementedError

    def make_response(self, key):
        """Generate the WebSocket handshake response string"""
        raise NotImplementedError


class MessageHandler:
    """Interface for message processing (read/parse/encode)"""
    def read_message(self, handler):
        """Read and parse a complete message from handler stream"""
        raise NotImplementedError

    def encode_message(self, message):
        """Encode message into wire format (bytes)"""
        raise NotImplementedError


class ClientManager:
    """Interface for client lifecycle management"""
    def add_client(self, client):
        """Register a new client"""
        raise NotImplementedError

    def remove_client(self, client):
        """Remove a disconnected client"""
        raise NotImplementedError

    def get_client_for_handler(self, handler):
        """Find client dictionary for a given handler"""
        raise NotImplementedError


class MessageBroadcaster:
    """Interface for message distribution"""
    def send_to_client(self, client, message):
        """Send message to specific client"""
        raise NotImplementedError

    def broadcast(self, message):
        """Send message to all connected clients"""
        raise NotImplementedError
